export type LineRange = { startLine: number; endLine: number; startColumn?: number; endColumn?: number };
export type InnerBbRef = `bb${number}`;
export type ShellBbRef = `shell:bb${number}`;
export type SourceLocation = { lineRanges?: LineRange[]; basicBlockRefs?: InnerBbRef[]; sourceRangeReason?: string; broadRangeReason?: string };
export type FunctionSource = { file: string; definitionRef: string; sourcePath: string; startLine: number; endLine: number; lines: string[]; attributeLines?: { startLine: number; endLine: number } };
export type SourceGroup = { id: string; label: string; lineRanges: LineRange[]; basicBlockRefs: InnerBbRef[]; sourceRangeReason?: string; broadRangeReason?: string };
/** Nodes with the same non-display field set, deep-equal lineRanges, and equal remaining content are identical even when basicBlockRefs differ; merge them or state distinctionReason on each. */
export type PreludeNode = { id: string; label: string; lineRanges: LineRange[]; basicBlockRefs: ShellBbRef[]; sourceRangeReason?: string; broadRangeReason?: string; distinctionReason?: string };
export type ShellTechnicalBlock = { bbRef: ShellBbRef; category: string; reason: string; evidenceRefs: ShellBbRef[]; factSha256: string; blockRole?: string; eventMacroProof?: unknown };
export type PreludeRelation = { shellBodyId: string; innerDefPathHash: string; constructionBbRef: ShellBbRef; innerMirSha256: string; shellMirSha256: string; instrumentBbRefs: ShellBbRef[]; intoFutureBbRefs: ShellBbRef[]; pollBbRefs: ShellBbRef[]; technicalBlocks: ShellTechnicalBlock[] };
export type Prelude = { shellBodyId: string; nodes: PreludeNode[]; relation: PreludeRelation };
/** Generated from the one JSON Schema. References and conditional path consistency are runtime checks. */
export type SafeId = string;
export type HexColor = string;
export type Actor = { "actorId": SafeId; "label": string; "kind": "crate" | "module" | "body" | "declaration"; "color": HexColor; "children"?: (Actor)[]; "alignment"?: "left" | "center" | "right"; "defaultExpanded"?: boolean; "parentActorId"?: SafeId | null; "className"?: string; "regionClassName"?: string; "sourceNodeRef"?: string; "bodyRef"?: string; "declarationRef"?: string; "implementationStatus"?: "unresolved" };
export type Message = { "messageId": SafeId; "fromActorId": SafeId; "toActorId": SafeId; "label": string; "kind": "request" | "return" | "self"; "pair": SafeId | null; "taskId"?: string; "handleId"?: string; "wrapperId"?: string; "pairState"?: "open"; "completion"?: "unknown"; "taskEvent"?: string; "attemptId"?: string; "resultId"?: string; "rowIndex"?: number; "invocationRef"?: string; "bindingRef"?: string; "awaitRef"?: string; "stage"?: string };
export type CaseIndexRow = [SafeId, string, string, string];
export type Repeat = { "scope"?: string; "continue": string; "exit": string; "limit"?: string; "maxRepeats"?: number };
export type ControlBranch = { "id": SafeId; "condition": string; "children": (Control)[]; "outcome"?: string };
export type Control = { "id": SafeId; "kind": "sequence"; "condition"?: string; "messages"?: (SafeId)[]; "children"?: (Control)[]; "notes"?: (string)[]; "after"?: (string)[]; "retainSummary"?: boolean; "invocationRef"?: string } | { "id": SafeId; "kind": "alt"; "condition"?: string; "messages"?: (SafeId)[]; "children"?: (Control)[]; "notes"?: (string)[]; "after"?: (string)[]; "retainSummary"?: boolean; "invocationRef"?: string; "branches": (ControlBranch)[] } | { "id": SafeId; "kind": "opt"; "condition"?: string; "messages"?: (SafeId)[]; "children"?: (Control)[]; "notes"?: (string)[]; "after"?: (string)[]; "retainSummary"?: boolean; "invocationRef"?: string; "skip": string } | { "id": SafeId; "kind": "loop"; "condition"?: string; "messages"?: (SafeId)[]; "children"?: (Control)[]; "notes"?: (string)[]; "after"?: (string)[]; "retainSummary"?: boolean; "invocationRef"?: string; "repeat": Repeat };
export type Segment = { "id": SafeId; "kind": "sequence"; "messages": (SafeId)[]; "notes"?: (string)[]; "condition"?: string; "invocationRef"?: string };
export type Action = SourceLocation & { "id": string; "renderId": SafeId; "label": string; "controlRefs": (SafeId)[]; "notes"?: (string)[] };
/** Multi-action goals require either mergeReason here or cohesionReason in the matching stage-2 goal contract. Adjacent goals with the same stage-2 completion contract and entry mode require splitReason here; no other field substitutes for it. */
export type Goal = SourceLocation & { "id": string; "renderId": SafeId; "label": string; "actions": (Action)[]; "notes"?: (string)[]; "mergeReason"?: string; "splitReason"?: string };
export type Phase = SourceLocation & { "id": SafeId; "label": string; "color": HexColor; "goals": (Goal)[]; "boundaryControlRefs": (SafeId)[]; "notes"?: (string)[] };
export type Owner = { "kind": "root" | "phase" | "action"; "ref": string };
export type ControlOwner = { "controlRef": SafeId; "owner": Owner };
export type MessagePlacement = { "messageRef": SafeId; "controlRef": SafeId; "rootControlRef": SafeId; "branchPath": (string)[] };
export type BranchRole = { "branchRef": SafeId; "controlRef": SafeId; "role": "business" | "normal" | "ready" | "pending" | "unwind" | "terminate-turn" | "cancelled" };
export type ReturnContract = { "messageRef": SafeId; "meaning": "normal-return" | "future-handle" | "poll-pending" | "task-ready"; "branchRef": string | null };
export type RootAnchor = { "controlRef": SafeId; "beforePhaseRef": SafeId; "actualOwner": "ROOT"; "bindingRef": string; "basis": string };
export type ScopeAnnotation = { "id": string; "kind": "sequence" | "alt" | "opt" | "loop"; "phaseRef": string; "phaseRefs"?: (string)[]; "actionRefs": (string)[]; "condition": string; "outcomes": (string)[]; "commonAfter": { "meaning": string; "appliesTo"?: (string)[]; "line"?: number } | null; "repeat"?: Repeat | null; "retainSummary"?: boolean };
export type PurposeProjection = { "id": string; "goalRef": string | null; "relatedGoalRefs": (string)[]; "defaultVisible": boolean; "summary": { "kind": "note"; "object": string; "purpose": string; "result": string; "drawAsMessage": false }; "invocationRefs": (string)[]; "waitRefs": (string)[] };
export type ReadingScope = { "id": string; "kind": "alt"; "condition": string; "members": ({ "kind": "phase" | "goal" | "action"; "ref": string })[]; "parentScopeRef": string | null; "originControlRef"?: string; "decision": { "variable": string; "values": (string)[] }; "commonAfter"?: { "actionRef": string; "label": string; "arrivals": ({ "path": string; "condition": string })[] }; "branches": ({ "id": string; "condition": string; "when": (string)[]; "members": ({ "kind": "phase" | "goal" | "action"; "ref": string })[]; "outcome"?: string; "sourceBranchRef"?: string; "effect"?: { "kind": "continue" | "terminate-turn"; "scopeRef": string } })[] } | { "id": string; "kind": "opt"; "condition": string; "members": ({ "kind": "phase" | "goal" | "action"; "ref": string })[]; "parentScopeRef": string | null; "originControlRef"?: string; "decision": { "variable": string; "values": (string)[] }; "commonAfter"?: { "actionRef": string; "label": string; "arrivals": ({ "path": string; "condition": string })[] }; "takeValues": (string)[]; "skipValues": (string)[]; "skip": string } | ({ "id": string; "kind": "loop"; "condition": string; "members": ({ "kind": "phase" | "goal" | "action"; "ref": string })[]; "parentScopeRef": string | null; "originControlRef"?: string; "decision": { "variable": string; "values": (string)[] }; "repeat": { "entryActionRef": string; "continueValues": (string)[]; "exitValues": (string)[]; "continue": string; "exit": string; "limit": string } } & ({ "commonAfter": { "actionRef": string; "label": string; "arrivals": ({ "path": string; "condition": string })[] }; "terminalOnly"?: never } | { "commonAfter"?: never; "terminalOnly": { "proofRef": string; "terminalNodeRefs": string[]; "exitEdgeRefs": string[] } }));
/** expandedActorIds contains only actors with children; all four arrays contain unique, existing IDs. */
export type InitialState = { "expandedActorIds": (string)[]; "expandedPhaseIds": (string)[]; "expandedGoalIds": (string)[]; "expandedActionIds": (string)[] };
export type TestBoundary = { "id": SafeId; "label": string; "actionRefs": (string)[]; "caseRefs": (string)[]; "reason": string };
export type Artifact = { "id": string; "sourcePath": string; "format": "rust" | "mir" | "icfg" | "fixture-source"; "sha256": string; "content": string };
export type Claim = { "kind": "entry" | "action" | "relation" | "decision" | "terminal" | "handoff" | "inventory" | "attachment" | "control-binding"; "subjectRef": string; "targets": (string)[]; "conditions": (string)[] };
export type Evidence = { "id": string; "artifactRef": string; "locator": string; "quote": string; "claim": Claim };
export type Guard = { "decisionRef": string; "value": string };
export type Decision = { "id": string; "values": (string)[]; "stability": "turn" | "iteration"; "evidenceRefs": (string)[]; "readingScopeRef"?: string; "controlRef"?: string; "branchBindings"?: ({ "branchRef": string; "values": (string)[] })[]; "takeValues"?: string[]; "skipValues"?: string[] };
export type ExecutionNode = SourceLocation & ({ "id": string; "label"?: string; "evidenceRefs": (string)[]; "kind": "entry" } | { "id": string; "label"?: string; "evidenceRefs": (string)[]; "actionRef": string; "kind": "action" } | { "id": string; "label"?: string; "evidenceRefs": (string)[]; "decisionRef": string; "kind": "decision" } | { "id": string; "label"?: string; "evidenceRefs": (string)[]; "outcome": "return" | "error" | "unwind" | "suspend"; "taskId"?: string; "kind": "terminal" } | { "id": string; "label"?: string; "evidenceRefs": (string)[]; "taskId": string; "event": "construct" | "await" | "resume" | "complete"; "kind": "handoff" });
export type ExecutionEdge = { "id": string; "from": string; "to": string; "kind": "flow" | "branch" | "call" | "return" | "await" | "resume" | "loop-continue" | "loop-exit"; "guards": (Guard)[]; "evidenceRefs": (string)[]; "taskId"?: string; "resetDecisionRefs"?: (string)[]; "readingScopeRef"?: string };
export type Attachment = { "id": string; "kind": "condition" | "identity" | "wait-explanation" | "purpose"; "ownerActionRef": string; "controlRef"?: string; "scopeAnnotationRef"?: string; "purposeRef"?: string; "evidenceRefs": (string)[] };
export type Execution = { "rootActorRef": string; "entryNodeRef": string; "inventory": { "actionRefs": (string)[]; "controlRefs": (string)[]; "evidenceRefs": (string)[] }; "artifacts": (Artifact)[]; "evidence": (Evidence)[]; "decisions": (Decision)[]; "nodes": (ExecutionNode)[]; "edges": (ExecutionEdge)[]; "attachments": (Attachment)[]; "tasks": ({ "id": string; "origin": "input" | "constructed"; "constructNodeRef"?: string; "evidenceRefs": (string)[] })[]; "controlBindings": ({ "controlRef": string; "nodeRef": string; "evidenceRefs": (string)[] })[] };
/** Runtime invariants: fixture is exactly {actors, messages:[]}; segments partition messages; derived owner/placement/role arrays equal control traversal; purpose refs resolve to invocations; commonAfter arrivals and return branches match their actual paths; evidence quotes occur literally in their artifact. */
export type CommonInput = { functionSource?: FunctionSource; sourceGroups?: SourceGroup[]; prelude?: Prelude; "profile": "v6.1/1"; "semanticRoot": { "actorRef": SafeId; "symbol": string }; "actors": (Actor)[]; "messages": (Message)[]; "phases": (Phase)[]; "segments": (Segment)[]; "fixture": { "actors": (Actor)[]; "messages": [] }; "controls": (Control)[]; "rootControlRefs": (SafeId)[]; "rootAnchors": (RootAnchor)[]; "scopeAnnotations": (ScopeAnnotation)[]; "purposeProjections": (PurposeProjection)[]; "initialState": InitialState; "display": { "title": string; "description": string; "sourceLabel": string }; "caseIndex": (CaseIndexRow)[]; "definitionNotes": (string)[]; "readingScopes": (ReadingScope)[]; "controlOwners": (ControlOwner)[]; "messagePlacements": (MessagePlacement)[]; "branchRoles": (BranchRole)[]; "returnContracts": (ReturnContract)[] };
export type RendererInput = CommonInput & ({deliveryMode:'test-suite';dataKind:'synthetic';execution:null;testBoundaries:TestBoundary[]} | {deliveryMode:'real-flow';dataKind:'source-backed';functionSource:FunctionSource;sourceGroups:SourceGroup[];execution:Execution;testBoundaries:[]});
export interface ValidationResult {valid:boolean;profile:'v6.1/1';errors:{code:string;path:string;message:string}[];proof?:string}
